acceptance.command:
node --input-type=module -e 'import assert from "node:assert/strict";
import { execFileSync } from "node:child_process";
import { mkdtempSync, writeFileSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
const dir = mkdtempSync(join(tmpdir(), "scope-865-"));
const git = (...args) => execFileSync("git", args, { cwd: dir, encoding: "utf8", stdio: ["ignore", "pipe", "pipe"] });
const write = (name, value) => writeFileSync(join(dir, name), value);
try {
  git("init", "-q");
  git("config", "user.name", "Scope fixture");
  git("config", "user.email", "scope@example.invalid");
  git("config", "commit.gpgsign", "false");
  write("allowed.txt", "base\n");
  write("protected.txt", "base\n");
  git("add", ".");
  git("commit", "-qm", "base");
  const base = git("rev-parse", "HEAD").trim();
  write("allowed.txt", "allowed change\n");
  git("add", "allowed.txt");
  git("commit", "-qm", "allowed");
  const allowed = git("rev-parse", "HEAD").trim();
  const reset = () => { git("reset", "--hard", allowed); git("clean", "-fd"); };
  const protectedChange = () => write("protected.txt", "protected change\n");
  const commitProtected = () => { protectedChange(); git("add", "protected.txt"); git("commit", "-qm", "protected"); };
  const restore = () => {
    git("restore", "--worktree", "--source=" + base, "--", "protected.txt");
    assert.equal(git("diff", base, "--", "protected.txt"), "");
  };
  const row = (name, expected) => {
    let protectedPass = true;
    try { git("diff", "--exit-code", base, "HEAD", "--", "protected.txt"); } catch { protectedPass = false; }
    const actual = [
      git("diff", "--name-only", base, "HEAD").trim() === "allowed.txt",
      git("diff", "--name-only", "--cached") === "",
      git("diff", "--name-only") === "",
      git("status", "--porcelain") === "",
      protectedPass
    ].map(value => value ? "P" : "F").join(" ");
    console.log(name + " " + actual);
    assert.equal(actual, expected);
  };
  row("S1", "P P P P P");
  commitProtected(); row("S2", "F P P P F");
  reset(); protectedChange(); row("S3", "P P F F P");
  reset(); protectedChange(); git("add", "protected.txt"); row("S4", "P F P F P");
  restore(); row("S5", "P F F F P");
  reset(); commitProtected(); restore(); row("S6", "F P F F F");
  reset(); write("extra.txt", "untracked\n"); row("S7", "P P P F P");
  reset(); row("S8", "P P P P P");
} finally { rmSync(dir, { recursive: true, force: true }); }'
